    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    max-width: 500px;
    cursor: pointer;
}

.toggle-row span {
    font-weight: 500;
    color: #2d3748;
}

.toggle-switch {
    width: 2.5rem;
    height: 1.25rem;
    cursor: pointer;
    accent-color: #3182ce;
}

