}

.preview-button {
    padding: 0.4rem 1rem;
    border-radius: 4px;
    border: none;
    background: #3182ce;
    color: #fff;
    cursor: pointer;
    font-size: 0.9em;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    padding: 0.85rem 1.25rem;
    border-radius: 8px;
    font-weight: 500;
    display: flex;
